code_sketch:
dec := json.NewDecoder(r)
dec.UseNumber()
var doc map[string]any
dec.Decode(&doc)              // numbers are now json.Number, not float64

// typed accessor that converts to int64 only when it knows the field is an integer
func Int(doc map[string]any, key string) (int64, bool) {
    if n, ok := doc[key].(json.Number); ok {
        v, err := n.Int64()
        if err != nil { return 0, false }
        return v, true
    }
    return 0, false
}

